/**
 * The athletes of the 3D stage: articulated low-poly bodies generated by
 * code, drawn with one instanced mesh per body part (a whole squad costs a
 * dozen draw calls). Render-only; poses come from `pose.ts`.
 */
import type * as ThreeTypes from 'three';
import { LEG, hipHeight, type Pose } from './pose';

type Three = typeof ThreeTypes;

export interface AthleteLook {
  readonly shirt: string;
  readonly sleeve: string;
  readonly shorts: string;
  readonly socks: string;
  readonly boots: string;
  readonly skin: string;
  readonly hair: string;
  readonly numberInk: string;
  readonly number: number;
}

/** Athletes are drawn a little larger than life so they read from the gantry. */
export const ATHLETE_SCALE = 1.16;
/** Height of the top of the head, for labels and markers. */
export const ATHLETE_HEIGHT = 1.86 * ATHLETE_SCALE;

const SKIN = ['#f1c9a5', '#e0ac7e', '#c68a5c', '#a56b43', '#7b4b2a', '#5a3620'];
const HAIR = ['#17120f', '#2a1b12', '#4a2f1b', '#8a5a2b', '#c9a15a', '#d8d2c8'];
const BOOTS = [
  '#111316',
  '#f4f4f0',
  '#ff5a1f',
  '#18c2ff',
  '#e7ff54',
  '#111316',
];

function hash(text: string): number {
  let value = 2_166_136_261;
  for (let index = 0; index < text.length; index += 1) {
    value ^= text.charCodeAt(index);
    value = Math.imul(value, 16_777_619);
  }
  return value >>> 0;
}

/** Stable skin, hair and boots for an athlete id. Pure. */
export function physiqueFor(id: string) {
  const value = hash(id);
  return {
    skin: SKIN[value % SKIN.length]!,
    hair: HAIR[(value >>> 5) % HAIR.length]!,
    boots: BOOTS[(value >>> 11) % BOOTS.length]!,
  };
}

const NUMBER_GRID = 10;

function numberAtlas(): HTMLCanvasElement {
  const cell = 128;
  const canvas = document.createElement('canvas');
  canvas.width = cell * NUMBER_GRID;
  canvas.height = cell * NUMBER_GRID;
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  context.fillStyle = '#ffffff';
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.font = '900 96px "Arial Narrow", "Helvetica Neue", Arial, sans-serif';
  for (let number = 0; number < NUMBER_GRID * NUMBER_GRID; number += 1) {
    const column = number % NUMBER_GRID;
    const row = Math.floor(number / NUMBER_GRID);
    context.fillText(
      String(number),
      column * cell + cell / 2,
      row * cell + cell / 2 + 6,
      cell - 14,
    );
  }
  return canvas;
}

export interface Athletes {
  readonly group: ThreeTypes.Group;
  setLook(index: number, look: AthleteLook): void;
  /** Places an athlete; `facing` is the yaw (0 looks at +Z). */
  place(
    index: number,
    x: number,
    z: number,
    facing: number,
    pose: Pose,
    visible: boolean,
  ): void;
  /** Uploads the frame's matrices. Call once after every `place`. */
  commit(): void;
  setShadows(enabled: boolean): void;
  dispose(): void;
}

export function createAthletes(
  THREE: Three,
  count: number,
  options: Readonly<{ shadows: boolean; anisotropy: number }>,
): Athletes {
  const group = new THREE.Group();
  group.name = 'athletes';
  const disposables: Array<{ dispose(): void }> = [];
  const track = <T extends { dispose(): void }>(item: T): T => {
    disposables.push(item);
    return item;
  };

  const cloth = () =>
    track(new THREE.MeshStandardMaterial({ roughness: 0.82, metalness: 0 }));
  const meshes: ThreeTypes.InstancedMesh[] = [];
  const part = (
    geometry: ThreeTypes.BufferGeometry,
    perAthlete: number,
    material: ThreeTypes.Material = cloth(),
  ) => {
    const mesh = new THREE.InstancedMesh(
      track(geometry),
      material,
      count * perAthlete,
    );
    mesh.frustumCulled = false;
    mesh.castShadow = options.shadows;
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    group.add(mesh);
    meshes.push(mesh);
    return mesh;
  };

  // --- Body parts, each modelled around its own joint. ---------------------
  const torsoGeometry = new THREE.CylinderGeometry(0.205, 0.165, 0.5, 14, 1);
  torsoGeometry.scale(1, 1, 0.62);
  torsoGeometry.translate(0, 0.3, 0);
  const shouldersGeometry = new THREE.SphereGeometry(
    0.205,
    14,
    8,
    0,
    Math.PI * 2,
    0,
    Math.PI / 2,
  );
  shouldersGeometry.scale(1, 0.32, 0.62);
  shouldersGeometry.translate(0, 0.55, 0);
  const shortsGeometry = new THREE.CylinderGeometry(0.17, 0.19, 0.25, 14, 1);
  shortsGeometry.scale(1, 1, 0.7);
  shortsGeometry.translate(0, -0.05, 0);
  const headGeometry = new THREE.SphereGeometry(0.108, 16, 12);
  headGeometry.scale(0.94, 1.08, 1);
  const hairGeometry = new THREE.SphereGeometry(
    0.115,
    16,
    8,
    0,
    Math.PI * 2,
    0,
    1.7,
  );
  hairGeometry.scale(0.95, 1.06, 1.02);
  hairGeometry.rotateX(-0.32);
  const upperArmGeometry = new THREE.CapsuleGeometry(0.05, 0.2, 3, 8);
  upperArmGeometry.translate(0, -0.14, 0);
  const forearmGeometry = new THREE.CapsuleGeometry(0.04, 0.21, 3, 8);
  forearmGeometry.translate(0, -0.14, 0);
  const thighGeometry = new THREE.CapsuleGeometry(0.08, 0.28, 3, 8);
  thighGeometry.translate(0, -0.2, 0);
  const shinGeometry = new THREE.CapsuleGeometry(0.057, 0.32, 3, 8);
  shinGeometry.translate(0, -0.21, 0);
  const footGeometry = new THREE.BoxGeometry(0.095, 0.075, 0.26);
  footGeometry.translate(0, -0.03, 0.07);
  const numberGeometry = new THREE.PlaneGeometry(0.25, 0.25);
  numberGeometry.rotateY(Math.PI);
  numberGeometry.translate(0, 0.36, -0.131);

  const skinMaterial = () =>
    track(new THREE.MeshStandardMaterial({ roughness: 0.6, metalness: 0 }));
  const torso = part(torsoGeometry, 1);
  const shoulders = part(shouldersGeometry, 1);
  const shorts = part(shortsGeometry, 1);
  const head = part(headGeometry, 1, skinMaterial());
  const hair = part(hairGeometry, 1);
  const upperArm = part(upperArmGeometry, 2);
  const forearm = part(forearmGeometry, 2, skinMaterial());
  const thigh = part(thighGeometry, 2, skinMaterial());
  const shin = part(shinGeometry, 2);
  const foot = part(
    footGeometry,
    2,
    track(new THREE.MeshStandardMaterial({ roughness: 0.4, metalness: 0.1 })),
  );

  // --- Shirt numbers: one atlas, one quad per athlete. ---------------------
  const atlas = track(new THREE.CanvasTexture(numberAtlas()));
  atlas.colorSpace = THREE.SRGBColorSpace;
  atlas.anisotropy = options.anisotropy;
  const cells = new Float32Array(count * 2);
  const cellAttribute = new THREE.InstancedBufferAttribute(cells, 2);
  numberGeometry.setAttribute('aCell', cellAttribute);
  const numberMaterial = track(
    new THREE.MeshBasicMaterial({
      map: atlas,
      transparent: true,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -2,
    }),
  );
  numberMaterial.onBeforeCompile = (shader) => {
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec2 aCell;')
      .replace(
        '#include <uv_vertex>',
        `#include <uv_vertex>\nvMapUv = (vMapUv + aCell) / ${NUMBER_GRID}.0;`,
      );
  };
  const numbers = part(numberGeometry, 1, numberMaterial);
  numbers.castShadow = false;

  // --- Soft contact shadows under every athlete. ---------------------------
  const blobCanvas = document.createElement('canvas');
  blobCanvas.width = 64;
  blobCanvas.height = 64;
  const blobContext = blobCanvas.getContext('2d');
  if (blobContext) {
    const gradient = blobContext.createRadialGradient(32, 32, 2, 32, 32, 31);
    gradient.addColorStop(0, 'rgba(0,0,0,0.75)');
    gradient.addColorStop(0.55, 'rgba(0,0,0,0.32)');
    gradient.addColorStop(1, 'rgba(0,0,0,0)');
    blobContext.fillStyle = gradient;
    blobContext.fillRect(0, 0, 64, 64);
  }
  const blobGeometry = new THREE.PlaneGeometry(1.5, 1.5);
  blobGeometry.rotateX(-Math.PI / 2);
  const blobs = part(
    blobGeometry,
    1,
    track(
      new THREE.MeshBasicMaterial({
        map: track(new THREE.CanvasTexture(blobCanvas)),
        transparent: true,
        depthWrite: false,
        opacity: 0.55,
      }),
    ),
  );
  blobs.castShadow = false;
  blobs.renderOrder = 1;

  // --- Forward kinematics. -------------------------------------------------
  const root = new THREE.Matrix4();
  const chest = new THREE.Matrix4();
  const upper = new THREE.Matrix4();
  const lower = new THREE.Matrix4();
  const end = new THREE.Matrix4();
  const local = new THREE.Matrix4();
  const euler = new THREE.Euler();
  const zero = new THREE.Matrix4().makeScale(0, 0, 0);
  const colour = new THREE.Color();
  const scaleVector = new THREE.Vector3(
    ATHLETE_SCALE,
    ATHLETE_SCALE,
    ATHLETE_SCALE,
  );

  /** `out = parent * T(x, y, z) * Rz(rz) * Rx(rx) * Ry(ry)`. */
  const joint = (
    out: ThreeTypes.Matrix4,
    parent: ThreeTypes.Matrix4,
    x: number,
    y: number,
    z: number,
    rx: number,
    rz = 0,
    ry = 0,
  ) => {
    local.makeRotationFromEuler(euler.set(rx, ry, rz, 'ZXY'));
    local.setPosition(x, y, z);
    out.multiplyMatrices(parent, local);
  };

  const limb = (index: number, side: 1 | -1, pose: Pose) => {
    const slot = index * 2 + (side === 1 ? 0 : 1);
    const hip = side === 1 ? pose.hipL : pose.hipR;
    const knee = side === 1 ? pose.kneeL : pose.kneeR;
    const shoulder = side === 1 ? pose.shoulderL : pose.shoulderR;
    const out = side === 1 ? pose.armOutL : pose.armOutR;
    const elbow = side === 1 ? pose.elbowL : pose.elbowR;
    // Leg: hip -> knee -> ankle. Forward swing is a negative X rotation.
    joint(upper, root, side * 0.098, -0.03, 0, -hip);
    thigh.setMatrixAt(slot, upper);
    joint(lower, upper, 0, -LEG.thigh, 0, knee);
    shin.setMatrixAt(slot, lower);
    joint(end, lower, 0, -LEG.shin + 0.05, 0, (hip - knee) * 0.7);
    foot.setMatrixAt(slot, end);
    // Arm: shoulder -> elbow.
    joint(upper, chest, side * 0.245, 0.5, 0, -shoulder, side * out);
    upperArm.setMatrixAt(slot, upper);
    joint(lower, upper, 0, -0.275, 0, -elbow);
    forearm.setMatrixAt(slot, lower);
  };

  const hide = (index: number) => {
    for (const mesh of [torso, shoulders, shorts, head, hair, numbers, blobs])
      mesh.setMatrixAt(index, zero);
    for (const mesh of [upperArm, forearm, thigh, shin, foot]) {
      mesh.setMatrixAt(index * 2, zero);
      mesh.setMatrixAt(index * 2 + 1, zero);
    }
  };

  const paint = (mesh: ThreeTypes.InstancedMesh, index: number, hex: string) =>
    mesh.setColorAt(index, colour.set(hex));

  for (let index = 0; index < count; index += 1) hide(index);

  return {
    group,
    setLook(index, look) {
      paint(torso, index, look.shirt);
      paint(shoulders, index, look.shirt);
      paint(shorts, index, look.shorts);
      paint(head, index, look.skin);
      paint(hair, index, look.hair);
      paint(numbers, index, look.numberInk);
      paint(blobs, index, '#ffffff');
      for (const offset of [0, 1]) {
        paint(upperArm, index * 2 + offset, look.sleeve);
        paint(forearm, index * 2 + offset, look.skin);
        paint(thigh, index * 2 + offset, look.skin);
        paint(shin, index * 2 + offset, look.socks);
        paint(foot, index * 2 + offset, look.boots);
      }
      const value = Math.max(0, Math.min(99, Math.round(look.number)));
      cells[index * 2] = value % NUMBER_GRID;
      // Atlas rows run top to bottom; texture v runs bottom to top.
      cells[index * 2 + 1] = NUMBER_GRID - 1 - Math.floor(value / NUMBER_GRID);
      cellAttribute.needsUpdate = true;
      for (const mesh of meshes)
        if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    },
    place(index, x, z, facing, pose, visible) {
      if (!visible) {
        hide(index);
        return;
      }
      const height = hipHeight(pose) * ATHLETE_SCALE;
      local.makeRotationFromEuler(
        euler.set(pose.pitch, facing, pose.roll, 'YXZ'),
      );
      local.scale(scaleVector);
      local.setPosition(x, height, z);
      root.copy(local);
      joint(chest, root, 0, 0, 0, pose.lean, 0, pose.twist);
      torso.setMatrixAt(index, chest);
      shoulders.setMatrixAt(index, chest);
      numbers.setMatrixAt(index, chest);
      shorts.setMatrixAt(index, root);
      joint(upper, chest, 0, 0.71, 0, pose.headPitch);
      head.setMatrixAt(index, upper);
      hair.setMatrixAt(index, upper);
      limb(index, 1, pose);
      limb(index, -1, pose);
      // The contact shadow shrinks and fades as the body leaves the grass.
      const lift = Math.max(0, pose.jump);
      const spread = 1 + pose.drop * 0.9 - Math.min(0.4, lift * 0.5);
      local.makeScale(spread, 1, spread);
      local.setPosition(x, 0.03, z);
      blobs.setMatrixAt(index, local);
    },
    commit() {
      for (const mesh of meshes) mesh.instanceMatrix.needsUpdate = true;
    },
    setShadows(enabled) {
      for (const mesh of meshes)
        if (mesh !== numbers && mesh !== blobs) mesh.castShadow = enabled;
    },
    dispose() {
      disposables.forEach((item) => item.dispose());
      meshes.forEach((mesh) => mesh.dispose());
    },
  };
}
